package com.inventra.backend.service; import com.inventra.backend.dto.StockMovementResponse; import com.inventra.backend.model.StockMovement; import com.inventra.backend.repository.StockMovementRepository; import org.springframework.stereotype.Service; import java.util.*; @Service public class StockMovementService {private final StockMovementRepository repo;public StockMovementService(StockMovementRepository r){repo=r;}public List<StockMovementResponse> all(){return repo.findAllByOrderByCreatedAtDesc().stream().map(this::map).toList();}public List<StockMovementResponse> product(String id){return repo.findByProductIdOrderByCreatedAtDesc(id).stream().map(this::map).toList();}public List<StockMovementResponse> warehouse(String id){return repo.findByWarehouseIdOrderByCreatedAtDesc(id).stream().map(this::map).toList();}private StockMovementResponse map(StockMovement m){return new StockMovementResponse(m.getId(),m.getProductId(),m.getWarehouseId(),m.getType(),m.getQuantity(),m.getBalanceAfter(),m.getReferenceId(),m.getReason(),m.getCreatedAt());}}
